package com.app.service;
import com.app.exception.ValidationException; import java.math.*; import java.util.*;
public final class SharedSplitCalculator { private SharedSplitCalculator() {} public static Map<Long,BigDecimal> equal(BigDecimal total,List<Long> ids){ if(ids==null||ids.isEmpty()) throw new ValidationException("Select at least one participant"); BigDecimal value=total.setScale(2,RoundingMode.UNNECESSARY),base=value.divide(BigDecimal.valueOf(ids.size()),2,RoundingMode.DOWN),remainder=value.subtract(base.multiply(BigDecimal.valueOf(ids.size()))); Map<Long,BigDecimal> result=new LinkedHashMap<>(); for(Long id:ids){if(result.containsKey(id))throw new ValidationException("Duplicate participant");BigDecimal share=base;if(remainder.signum()>0){share=share.add(new BigDecimal("0.01"));remainder=remainder.subtract(new BigDecimal("0.01"));}result.put(id,share);}return result;} public static void requireTotal(BigDecimal total,Collection<BigDecimal> values){if(values.stream().reduce(BigDecimal.ZERO,BigDecimal::add).compareTo(total)!=0)throw new ValidationException("Share total must equal expense total");}}
